def write(path,text):
 p=ROOT/path; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(text,encoding='utf-8')
def route(lang,slug='index'):
 return ('' if lang=='en' else lang+'/') + ('' if slug=='index' else slug+'.html')
def local(lang,slug='index'):
 return ('' if lang=='en' else lang+'/') + slug+'.html'
def image(group,base='',eager=False):
 attr='fetchpriority="high"' if eager else 'loading="lazy"'
 return f'<img src="{base}img/{IMAGES[group]}" alt="{["Bedroom textile collection","Hospitality and spa collection","Baby textile collection"][group]}" width="1600" height="1067" {attr} decoding="async">'
def product_image(slug,lang,base='',eager=False):
 name=next(it[LABEL_INDEX[lang]] for it in ITEMS if it[0]==slug)
 qualifier={'en':'illustrative product visual','fr':'visuel illustratif du produit','de':'illustrative Produktdarstellung','es':'imagen ilustrativa del producto'}[lang]
 attr='fetchpriority="high"' if eager else 'loading="lazy"'
 return f'<img src="{base}img/products/{slug}.webp" srcset="{base}img/products/{slug}-768.webp 768w, {base}img/products/{slug}.webp 1536w" sizes="(max-width:760px) 88vw, (max-width:1100px) 44vw, 40vw" alt="{esc(name+" — "+qualifier,quote=True)}" width="1536" height="1024" {attr} decoding="async">'
def cards(lang,base='',group=None,exclude=None):
 t=L[lang]; out=''
 for i,it in enumerate(ITEMS):
  if group is not None and it[1]!=group: continue
  if it[0]==exclude: continue
  out+=f'<a class="product-tile reveal" href="{base}{local(lang,"collections/"+it[0])}"><div class="product-photo">{product_image(it[0],lang,base)}<span class="tile-number">{i+1:02}</span></div><div class="product-caption"><div><span class="eyebrow">{t["groups"][it[1]]}</span><h3>{it[LABEL_INDEX[lang]]}</h3></div><span class="arrow" aria-hidden="true">↗</span></div></a>'
 return out
