def cta(lang,base):
 t=L[lang]; return f'<section class="project-section"><div class="project-orbit" aria-hidden="true"></div><span class="eyebrow">TVS TEXTILE / LET’S CONNECT</span><h2>{t["project"]}</h2><p>{t["project_sub"]}</p><a class="button light" href="{base}{local(lang,"contact")}">{t["cta"]} <span>↗</span></a></section>'

def build():
 for lang,t in L.items():
  base='' if lang=='en' else '../'
  body=f'''<section class="hero"><div class="hero-copy"><span class="eyebrow">{t['tag']}</span><h1>{t['hero']}</h1><p>{t['intro']}</p><a class="button" href="#collections">{t['explore']} <span>↗</span></a><div class="hero-foot"><span>HOME / HOSPITALITY / BABY</span><span>SCROLL TO DISCOVER ↓</span></div></div><div class="hero-visual">{image(0,base,True)}<div class="hero-stamp"><img src="{base}img/tvslogo_yeni.webp" alt="TVS Tekstil" width="220" height="100"></div><div class="photo-caption"><span>01 — THE HOME COLLECTION</span><span>Softness, in every detail.</span></div></div></section>{connection_band(lang)}<section class="section" id="collections"><div class="section-heading reveal"><div><span class="eyebrow">01 / {t['nav'][0]}</span><h2>{t['collection']}</h2></div><p>{t['collection_sub']}</p></div>{groups(lang,base)}</section>'''
  stories={'en':('Rooted in Denizli.<br><em>Connected to your world.</em>','TVS Textile brings home, hospitality and baby textiles to international buyers from Denizli, Türkiye. We start with your product brief: the purpose, the feel and the details that matter to your business.'),'fr':('Ancrés à Denizli.<br><em>Ouverts sur votre monde.</em>','TVS Textile propose du linge de maison, des textiles hôteliers et des articles bébé aux acheteurs internationaux depuis Denizli, en Türkiye. Votre cahier des charges est le point de départ de notre échange.'),'de':('In Denizli verwurzelt.<br><em>Mit Ihrer Welt verbunden.</em>','TVS Textile bietet Heimtextilien, Hoteltextilien und Babytextilien für internationale Einkäufer aus Denizli in Türkiye. Ihr Produktbrief ist der Ausgangspunkt unseres Gesprächs.'),'es':('Con raíces en Denizli.<br><em>Conectados con su mundo.</em>','TVS Textile ofrece textiles para el hogar, hostelería y bebé a compradores internacionales desde Denizli, Türkiye. Su ficha de producto es el punto de partida de nuestra conversación.')}
  st,sp=stories[lang]
  body+=f'<section class="story-section"><div class="story-image">{image(2,base)}<span class="story-label">A CONSIDERED APPROACH</span></div><div class="story-copy reveal"><span class="eyebrow">02 / TVS TEXTILE</span><h2>{st}</h2><p>{sp}</p><a class="text-link" href="{base}{local(lang,"about")}">{t["about"]} ↗</a><div class="story-values"><span>{t["groups"][0]}</span><span>{t["groups"][1]}</span><span>{t["groups"][2]}</span></div></div></section><section class="section"><div class="section-heading"><div><span class="eyebrow">03 / {t["buyer"]}</span><h2>{t["spec"]}</h2></div><p>{t["brief"]}</p></div><div class="brief-grid">'+''.join(f'<div class="brief-card reveal"><span>0{i+1}</span><h3>{h}</h3><p>{p}</p></div>' for i,(h,p) in enumerate({ 'en':[('Define the product','Choose a collection and share the materials, sizes and details you need.'),('Discuss the brief','Ask about samples, minimum quantities and the specifications for your project.'),('Plan the next step','Confirm the quote, agreed specifications and destination before placing your order.')], 'fr':[('Définir le produit','Choisissez une collection et précisez matières, dimensions et détails.'),('Échanger sur le projet','Discutez des échantillons, quantités minimales et spécifications.'),('Préparer la suite','Confirmez le devis, les spécifications et la destination avant la commande.')], 'de':[('Produkt definieren','Wählen Sie die Kollektion und nennen Sie Material, Maße und Details.'),('Brief besprechen','Fragen Sie nach Mustern, Mindestmengen und Spezifikationen.'),('Nächsten Schritt planen','Bestätigen Sie Angebot, Spezifikationen und Zielland vor der Bestellung.')], 'es':[('Definir el producto','Elija una colección e indique materiales, medidas y detalles.'),('Comentar el proyecto','Consulte muestras, cantidades mínimas y especificaciones.'),('Planificar el siguiente paso','Confirme presupuesto, especificaciones y destino antes del pedido.')]}[lang]))+'</div></section>'+cta(lang,base)
  page(lang,'index', {'en':'Turkish Home, Hotel & Baby Textiles | TVS Textile','fr':'Linge de maison, hôtel & bébé de Turquie | TVS Textile','de':'Heim-, Hotel- & Babytextilien aus der Türkei | TVS Textile','es':'Textiles de hogar, hotel y bebé de Turquía | TVS Textile'}[lang],t['intro'],body)
  page(lang,'products',t['nav'][0]+' | TVS Textile',t['collection_sub']+' '+', '.join(it[LABEL_INDEX[lang]] for it in ITEMS[:3]),f'<section class="page-intro"><span class="eyebrow">THE TVS COLLECTIONS</span><h1>{t["collection"]}</h1><p>{t["collection_sub"]}</p></section><section class="section">{groups(lang,base)}<div class="product-list">{cards(lang,base)}</div></section>'+cta(lang,base))
  for g,slug in enumerate(GROUP_SLUGS):
   groupbase='../' if lang=='en' else '../../'
   origin={'en':'from Türkiye','fr':'de Turquie','de':'aus der Türkei','es':'de Turquía'}[lang]
   page(lang,'collections/'+slug,t['groups'][g]+' '+origin+' | TVS Textile',t['groups'][g]+': '+', '.join(it[LABEL_INDEX[lang]] for it in ITEMS if it[1]==g)+'. '+t['brief'],f'<section class="split-intro"><div><a class="eyebrow" href="{groupbase}{local(lang,"products")}">← {t["back"]}</a><h1>{t["groups"][g]}</h1><p>{t["brief"]}</p><a class="button" href="{groupbase}{local(lang,"contact")}">{t["cta"]} ↗</a></div><div>{image(g,groupbase,True)}</div></section><section class="section"><div class="product-list">{cards(lang,groupbase,g)}</div><p class="image-note">{t["note"]}</p></section>'+cta(lang,groupbase))
  for item_index,it in enumerate(ITEMS):
   slug,g=it[:2]; name=it[LABEL_INDEX[lang]]; b='../' if lang=='en' else '../../'
   detail=it[7] if lang=='en' else DETAILS[lang][item_index]
   summary=it[6] if lang=='en' else t['buyer']+' · '+t['groups'][g]
   body=f'<section class="split-intro"><div><a class="eyebrow" href="{b}{local(lang,"collections/"+GROUP_SLUGS[g])}">← {t["groups"][g]}</a><h1>{name}</h1><p>{summary}</p><a class="button" href="{b}{local(lang,"contact")}?product={slug}">{t["inquiry"]} ↗</a></div><div>{product_image(slug,lang,b,True)}</div></section><section class="section product-detail"><div><span class="eyebrow">{t["buyer"]}</span><h2>{t["spec"]}</h2><p>{detail}</p><p>{t["brief"]}</p></div><aside><h3>{t["inquiry"]}</h3><p>{name} / {t["groups"][g]}</p><a class="text-link" href="mailto:ozkan@tvstextile.com?subject={slug}">ozkan@tvstextile.com ↗</a><p class="image-note">{t["note"]}</p></aside></section><section class="section"><h2>{t["related"]}</h2><div class="product-list">{cards(lang,b,g,exclude=slug)}</div></section>'+cta(lang,b)
   suffix={'en':'Turkish Textile Manufacturer','fr':'Fabricant textile en Turquie','de':'Textilhersteller in der Türkei','es':'Fabricante textil en Turquía'}[lang]
   desc={'en':'Textile sourcing from Denizli, Türkiye. Discuss materials, dimensions, samples and order quantities with TVS Textile.','fr':'Textiles de Denizli, Turquie. Discutez des matières, dimensions, échantillons et quantités avec TVS Textile.','de':'Textilien aus Denizli, Türkei. Besprechen Sie Material, Maße, Muster und Bestellmengen mit TVS Textile.','es':'Textiles de Denizli, Turquía. Consulte materiales, medidas, muestras y cantidades con TVS Textile.'}[lang]
   page(lang,'collections/'+slug,name+' | '+suffix+' | TVS Textile',name+'. '+desc,body)
  page(lang,'about',t['about']+' | TVS Textile, Denizli',sp,f'<section class="page-intro"><span class="eyebrow">DENİZLİ, TÜRKİYE / TVS TEXTILE</span><h1>{st}</h1><p>{sp}</p></section><section class="section">{groups(lang,base)}</section><section class="section product-detail"><div><h2>{t["spec"]}</h2><p>{t["brief"]}</p></div><aside><h3>{t["contact"]}</h3><p>{ADDRESS}</p><a href="tel:+905324770375">+90 532 477 0375</a><p><a href="mailto:ozkan@tvstextile.com">ozkan@tvstextile.com</a></p></aside></section>'+cta(lang,base))
  build_contact(lang,base)
  build_guide(lang,base)
 build_legacy()
 paths=[p for p in ROOT.glob('*.html') if p.stem not in ['404','post','product-detail']]+list((ROOT/'collections').glob('*.html'))
 for lang in ['fr','de','es']: paths+=list((ROOT/lang).rglob('*.html'))
 write_sitemap(ROOT,paths)
 write('robots.txt','User-agent: *\nAllow: /\nDisallow: /admin/\nDisallow: /admin-panel/\nDisallow: /.private/\nDisallow: /tools/\nDisallow: /TVSTÜRKÇE/\nDisallow: /.git/\n\nSitemap: '+DOMAIN+'/sitemap.xml\n')

def build_contact(lang,base):
 t=L[lang]
 labels={'en':['Your name','Company','Email','Destination country','Product / collection','Estimated quantity','Your project brief','Prepare email enquiry','This form prepares an email in your email app. Review it and press Send there. Your enquiry is not sent by this website.'], 'fr':['Votre nom','Entreprise','E-mail','Pays de destination','Produit / collection','Quantité estimée','Votre projet','Préparer un e-mail','Ce formulaire prépare un e-mail dans votre messagerie. Vérifiez-le puis envoyez-le. Le site ne transmet pas votre demande.'], 'de':['Ihr Name','Unternehmen','E-Mail','Zielland','Produkt / Kollektion','Geschätzte Menge','Ihr Projekt','E-Mail-Anfrage vorbereiten','Dieses Formular öffnet eine E-Mail in Ihrem E-Mail-Programm. Prüfen und senden Sie sie dort. Die Website sendet Ihre Anfrage nicht.'], 'es':['Su nombre','Empresa','Correo electrónico','País de destino','Producto / colección','Cantidad estimada','Su proyecto','Preparar consulta por correo','Este formulario prepara un correo en su aplicación. Revíselo y envíelo allí. El sitio no envía su consulta.']}[lang]
 fields=''
 for i,key in enumerate(['name','subject','email','country','product','quantity']):
  if key=='product': control=f'<select id="{key}" name="{key}"><option value="">—</option>'+''.join(f'<option value="{it[0]}">{it[LABEL_INDEX[lang]]}</option>' for it in ITEMS)+'</select>'
  else: control=f'<input id="{key}" name="{key}" type="{"email" if key=="email" else "text"}" {"required" if key in ["name","email","country"] else ""} autocomplete="{ {"name":"name","subject":"organization","email":"email","country":"country-name"}.get(key,"off")}" maxlength="200">'
  fields+=f'<label for="{key}">{labels[i]}{control}</label>'
 send={'en':'Send enquiry','fr':'Envoyer la demande','de':'Anfrage senden','es':'Enviar consulta'}[lang]
 phone={'en':'Phone (optional)','fr':'Téléphone (facultatif)','de':'Telefon (optional)','es':'Teléfono (opcional)'}[lang]
 body=f'<section class="page-intro"><span class="eyebrow">LET’S CONNECT / TVS TEXTILE</span><h1>{t["project"]}</h1><p>{t["project_sub"]}</p></section><section class="section contact-layout"><div class="contact-details"><h2>{t["contact"]}</h2><a class="contact-email" href="mailto:ozkan@tvstextile.com">ozkan@tvstextile.com ↗</a><a href="tel:+905324770375">+90 532 477 0375</a><p>{ADDRESS}</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&amp;query=Ak%C3%A7e%C5%9Fme+2605+Sk+40+Merkezefendi+Denizli" target="_blank" rel="noopener">Google Maps ↗</a><p>{t["brief"]}</p></div><form id="enquiry-form" action="/admin/api/quotes" method="post"><div class="form-grid">{fields}</div><label for="phone">{phone}<input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="100"></label><label for="message">{labels[6]}<textarea id="message" name="message" rows="5" required maxlength="4000"></textarea></label><button class="button" type="submit">{send} ↗</button><p id="form-status" role="status" aria-live="polite"></p><noscript><p>Please email ozkan@tvstextile.com directly; JavaScript is needed to send this form.</p></noscript></form></section>'
 page(lang,'contact',t['contact']+' | Textile Enquiries | TVS Textile',t['project_sub'],body)

def build_guide(lang,base):
 t=L[lang]
 texts={'en': [('Start with the intended use','A home bedding collection, a hotel replenishment order and a baby range have different requirements. Explain the intended customer and use before choosing the textile specification.'),('Specify the details that affect the quote','Include dimensions, composition, fabric weight where relevant, colours, quantities per variant, finishing and packaging preferences. Share your destination and target schedule.'),('Request samples and supporting documents','Ask which samples and product documents are available for your brief. Confirm any required certification, laboratory testing or destination-market compliance against the actual product. No certification should be assumed from a category photograph.'),('Agree commercial and delivery terms','Confirm minimum quantities, sample approval, lead time, payment terms, shipping responsibility and the agreed delivery term in writing. These depend on the project and need a specific quotation.')], 'fr':[('Définir l’usage','Une collection pour la maison, un hôtel ou un bébé nécessite des spécifications différentes. Précisez le client et l’usage prévu.'),('Préciser les détails','Indiquez dimensions, composition, grammage, couleurs et quantités par variante. Ajoutez destination, emballage et calendrier souhaité.'),('Demander les documents','Vérifiez la disponibilité des échantillons et documents. Les certifications et essais doivent être confirmés pour le produit final et le marché visé.'),('Confirmer les conditions','Convenez par écrit des quantités minimales, échantillons, délais, paiement et responsabilités de transport. Ces conditions dépendent du projet.')], 'de':[('Verwendung festlegen','Heimtextilien, Hotelbedarf und Babyprodukte benötigen unterschiedliche Spezifikationen. Beschreiben Sie Kunden und Verwendungszweck.'),('Details angeben','Nennen Sie Maße, Zusammensetzung, Stoffgewicht, Farben und Mengen je Variante sowie Zielland, Verpackung und Zeitplan.'),('Dokumente anfordern','Fragen Sie nach Mustern und Produktunterlagen. Zertifikate und Prüfungen müssen für das tatsächliche Produkt und den Zielmarkt bestätigt werden.'),('Bedingungen bestätigen','Vereinbaren Sie Mindestmengen, Musterfreigabe, Lieferzeit, Zahlung und Transportverantwortung schriftlich. Diese Bedingungen sind projektabhängig.')], 'es':[('Definir el uso','Hogar, hotel y bebé necesitan especificaciones diferentes. Describa el cliente y el uso previsto.'),('Indicar los detalles','Incluya medidas, composición, gramaje, colores y cantidades por variante, además del destino, embalaje y calendario.'),('Solicitar documentación','Consulte muestras y documentos disponibles. Certificaciones y ensayos deben verificarse para el producto final y el mercado de destino.'),('Confirmar las condiciones','Acuerde por escrito cantidades mínimas, muestras, plazos, pago y responsabilidades de transporte. Estas condiciones dependen del proyecto.')]}[lang]
 body=f'<section class="page-intro"><span class="eyebrow">FOR INTERNATIONAL BUYERS</span><h1>{t["guide"]}</h1><p>{t["brief"]}</p></section><section class="section guide-list">'+''.join(f'<article class="guide-row reveal"><span>0{i+1}</span><div><h2>{h}</h2><p>{p}</p></div></article>' for i,(h,p) in enumerate(texts))+'</section>'+cta(lang,base)
 page(lang,'sourcing-guide',t['guide']+' | Buying Textiles from Türkiye | TVS Textile',t['brief'],body)

